import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Problembehandlung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/troubleshooting.md","filePath":"de/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`de/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="problembehandlung" tabindex="-1">Problembehandlung <a class="header-anchor" href="#problembehandlung" aria-label="Permalink to “Problembehandlung”">​</a></h1><p>Diese Seite sammelt häufige Probleme und zeigt, wie Sie sie beheben.</p><h2 id="die-app-startet-nicht-oder-sturzt-beim-start-ab" tabindex="-1">Die App startet nicht oder stürzt beim Start ab <a class="header-anchor" href="#die-app-startet-nicht-oder-sturzt-beim-start-ab" aria-label="Permalink to “Die App startet nicht oder stürzt beim Start ab”">​</a></h2><p>Symptome: Sudoku öffnet sich nicht, stürzt sofort ab oder zeigt einen unerwarteten Fehler.</p><p>Schritte zum Ausprobieren:</p><ol><li>Stellen Sie sicher, dass Ihr Gerät die Mindestanforderungen erfüllt (iOS/iPadOS 16+, macOS 15+).</li><li>Beenden Sie die App erzwungen und starten Sie sie erneut.</li><li>Starten Sie Ihr Gerät neu.</li><li>Installieren Sie die App aus dem App Store neu.</li><li>Wenn das Problem weiterhin besteht, eröffnen Sie ein Issue im Projekt-Repository mit den Details.</li></ol><h2 id="leistungsprobleme" tabindex="-1">Leistungsprobleme <a class="header-anchor" href="#leistungsprobleme" aria-label="Permalink to “Leistungsprobleme”">​</a></h2><p>Wenn das Spiel ruckelt oder langsam ist:</p><ol><li>Schließen Sie andere ressourcenintensive Anwendungen.</li><li>Prüfen Sie auf dem Mac die Aktivitätsanzeige auf hohe CPU-Auslastung.</li><li>Wählen Sie auf älteren Geräten einen leichteren Schwierigkeitsgrad (Leicht oder Mittel).</li></ol><h2 id="icloud-synchronisierung-funktioniert-nicht" tabindex="-1">iCloud-Synchronisierung funktioniert nicht <a class="header-anchor" href="#icloud-synchronisierung-funktioniert-nicht" aria-label="Permalink to “iCloud-Synchronisierung funktioniert nicht”">​</a></h2><p>Wenn Ihr Fortschritt nicht zwischen Geräten synchronisiert wird:</p><ol><li>Stellen Sie sicher, dass Sie auf allen Geräten mit derselben Apple-ID angemeldet sind.</li><li>Prüfen Sie, ob iCloud Drive in den Systemeinstellungen (Mac) bzw. Einstellungen (iOS/iPadOS) aktiviert ist.</li><li>Vergewissern Sie sich, dass eine aktive Internetverbindung besteht.</li><li>Schalten Sie iCloud für Sudoku in den Einstellungen unter [Ihr Name] → iCloud → Apps, die iCloud verwenden, aus und wieder ein.</li><li>Starten Sie alle Geräte neu und versuchen Sie es erneut.</li></ol><h2 id="game-center-stellt-keine-verbindung-her" tabindex="-1">Game Center stellt keine Verbindung her <a class="header-anchor" href="#game-center-stellt-keine-verbindung-her" aria-label="Permalink to “Game Center stellt keine Verbindung her”">​</a></h2><p>Wenn Game Center-Erfolge oder Ranglisten nicht aktualisiert werden:</p><ol><li>Stellen Sie sicher, dass Sie bei Game Center angemeldet sind (iOS: Einstellungen → Game Center; Mac: Systemeinstellungen).</li><li>Prüfen Sie Ihre Internetverbindung.</li><li>Melden Sie sich bei Game Center ab und wieder an.</li></ol><h2 id="protokolle-anzeigen" tabindex="-1">Protokolle anzeigen <a class="header-anchor" href="#protokolle-anzeigen" aria-label="Permalink to “Protokolle anzeigen”">​</a></h2><p>Zur Fehleranalyse von Abstürzen sind Anwendungsprotokolle hilfreich. In sandboxed Builds (App Store) auf dem Mac finden Sie diese unter:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>Unter iOS/iPadOS verbinden Sie Ihr Gerät mit einem Mac und zeigen die Protokolle in Console.app an, gefiltert nach „Sudoku“.</p><h2 id="app-zurucksetzen" tabindex="-1">App zurücksetzen <a class="header-anchor" href="#app-zurucksetzen" aria-label="Permalink to “App zurücksetzen”">​</a></h2><p>So setzen Sie die Einstellungen zurück und löschen lokale Daten (Mac):</p><ol><li>Beenden Sie Sudoku</li><li>Entfernen Sie den Container (Vorsicht – dabei werden alle Einstellungen, Statistiken und Spielstände gelöscht):</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>Öffnen Sie Sudoku erneut und richten Sie die App neu ein.</li></ol><p>Unter iPhone/iPad löschen Sie die App und installieren Sie sie neu, um alle Daten zurückzusetzen.</p><p><strong>Hinweis</strong>: Wenn Sie die iCloud-Synchronisierung nutzen, kann ein Zurücksetzen auf einem Gerät dazu führen, dass die Daten nach dem Neustart erneut aus iCloud geladen werden. Für ein vollständiges Zurücksetzen auf allen Geräten müssen Sie die App möglicherweise auf jedem Gerät zurücksetzen.</p><h2 id="problem-melden" tabindex="-1">Problem melden <a class="header-anchor" href="#problem-melden" aria-label="Permalink to “Problem melden”">​</a></h2><p>Wenn Sie ein Issue eröffnen, geben Sie bitte an:</p><ul><li>Gerätetyp (iPhone, iPad oder Mac)</li><li>Betriebssystemversion (Einstellungen → Allgemein → Info)</li><li>Sudoku-Version (Einstellungen → Über)</li><li>Schritte zum Reproduzieren</li><li>Protokolle oder Screenshots, falls verfügbar</li></ul><p>So können Maintainer das Problem schneller eingrenzen und beheben.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};